def get_random_direction(self, point: np.ndarray) -> np.ndarray:

    fibril_orientation = self.fibril_orientation_params.fibril_orientation

    if fibril_orientation == FibrilOrientation.RANDOM_FLAT:
        theta = np.deg2rad(np.random.normal(90, 30))  # Centered orthogonal to z-axis
        psi   = np.deg2rad(np.random.uniform(0, 360)) # Any direction in xy-plane

    elif fibril_orientation == FibrilOrientation.RANDOM_VERY_FLAT:
        theta = np.deg2rad(np.random.normal(90, 1.0))  # Centered very orthogonal to z-axis
        psi   = np.deg2rad(np.random.uniform(0, 360))  # Any direction in xy-plane

    elif fibril_orientation == FibrilOrientation.GRF_SAMPLE_FLAT:
        theta = np.deg2rad(np.random.normal(90, 30))   # Centered orthogonal to z-axis
        psi   = self.psi_ref[tuple(point.astype(int))] # Lookup GRF sampled angle

    elif fibril_orientation == FibrilOrientation.GRF_SAMPLE_ALL:
        theta = self.theta_ref[tuple(point.astype(int))] # Lookup GRF sampled angle
        psi   = self.psi_ref[tuple(point.astype(int))]   # Lookup GRF sampled angle

    # Convert Euler angles to unit vector
    direction = np.asarray([np.sin(theta)*np.cos(psi), np.sin(theta)*np.sin(psi), np.cos(theta)])
    return direction / np.linalg.norm(direction)

    def loadRun(
        self,
        run,
        dims=None,
        coords={},
        return_dataset=False,
        useMonitorShutterThinning=True,
     ):
        """
        Loads a run entry from a catalog result into a raw xarray.

        Args:
            run (DataBroker result, int of a scan id, list of scan ids, list of DataBroker runs): a single run from BlueSky
            dims (list): list of dimensions you'd like in the resulting xarray.  See list of allowed dimensions in documentation.  If not set or None, tries to auto-hint the dims from the RSoXS plan_name.
            CHANGE: List of dimensions you'd like. If not set, will set all possibilities as dimensions (x, y, theta, energy, polarization)
            coords (dict): user-supplied dimensions, see syntax examples in documentation.
            return_dataset (bool,default False): return both the data and the monitors as a xr.dataset.  If false (default), just returns the data.
        Returns:
            raw (xarray): raw xarray containing your scan in PyHyper-compliant format

        """
        if isinstance(run,int):
            run = self.c[run]
        elif isinstance(run,pd.DataFrame):
            run = list(run.scan_id)
        if isinstance(run,list):
            return self.loadSeries(
                run,
                "sample_name",
                loadrun_kwargs={
                    "dims": dims,
                    "coords": coords,
                    "return_dataset": return_dataset,
                },
            )

        md = self.loadMd(run)


        monitors = self.loadMonitors(run)

        if dims is None:
            if ("NEXAFS" or "nexafs") in md["start"]["plan_name"]:
                raise NotImplementedError(
                    f"Scan {md['start']['scan_id']} is a {md['start']['plan_name']} NEXAFS scan. "
                    " NEXAFS loading is not yet supported."
                )  # handled case change in "NEXAFS"
            elif (
                "full" in md["start"]["plan_name"]
                or "short" in md["start"]["plan_name"]
                or "custom_rsoxs_scan" in md["start"]["plan_name"]
            ) and dims is None:
                dims = ["energy"]
            elif "spiralsearch" in md["start"]["plan_name"] and dims is None:
                dims = ["sam_x", "sam_y"]
            elif "count" in md["start"]["plan_name"] and dims is None:
                dims = ["time"]
            else:
                axes_to_include = []
                rsd_cutoff = 0.005

                # begin with a list of the things that are primary streams
                axis_list = list(run["primary"]["data"].keys())

                # next, knock out anything that has 'image', 'fullframe' in it - these aren't axes
                axis_list = [x for x in axis_list if "image" not in x]
                axis_list = [x for x in axis_list if "fullframe" not in x]
                axis_list = [x for x in axis_list if "stats" not in x]
                axis_list = [x for x in axis_list if "saturated" not in x]
                axis_list = [x for x in axis_list if "under_exposed" not in x]

                # remove new detector terms #193
                axis_list = [x for x in axis_list if "acquire_time" not in x]
                axis_list = [x for x in axis_list if "tiff_time_stamp" not in x]


                # remove hinted Energy and EPU60 items #161
                axis_list = [x for x in axis_list if "EPU60" not in x]
                axis_list = [x for x in axis_list if "Energy" not in x]

                # knock out any known names of scalar counters
                axis_list = [x for x in axis_list if "Beamstop" not in x]
                axis_list = [x for x in axis_list if "Current" not in x]

                if self.suppress_time_dimension:
                    axis_list = [x for x in axis_list if x != "time"]

                # now, clean up duplicates.
                axis_list = [x for x in axis_list if "setpoint" not in x]
                # now, figure out what's actually moving.  we use a relative standard deviation to do this.
                # arbitrary cutoff of 0.5% motion = it moved intentionally.
                for axis in axis_list:
                    std = np.std(run["primary"]["data"][axis])
                    motion = np.abs(np.max(run["primary"]["data"][axis])-np.min(run["primary"]["data"][axis]))
                    if motion == 0:
                        rsd = 0
                    else:
                        rsd = std / motion
                    # print(f'Evaluating {axis} for inclusion as a dimension with rsd {rsd}...')
                    if rsd > rsd_cutoff:
                        axes_to_include.append(axis)
                        # print(f'    --> it was included')

                # next, construct the reverse lookup table - best mapping we can make of key to pyhyper word
                # we start with the lookup table used by loadMd()
                reverse_lut = {md_key_beamline: md_key_PHS 
                               for md_key_PHS, md_key_beamline_list in self.md_lookup.items() 
                               for md_key_beamline in md_key_beamline_list}
# this creates a reverse mapping where the keys are the possible names in 'beamline language' of a parameter, and the values are the name in 'PyHyper language'.  This exploits the fact that dicts are ordered to provide rank-sorted mapping of parameters.
                # here, we broaden the table to make a value that default sources from '_setpoint' actually match on either
                # the bare value or the readback value.
                reverse_lut_adds = {}
                for k in reverse_lut.keys():
                    if "setpoint" in k:
                        reverse_lut_adds[k.replace("_setpoint", "")] = reverse_lut[k]
                        reverse_lut_adds[k.replace("_setpoint", "_readback")] = reverse_lut[k]
                reverse_lut.update(reverse_lut_adds)

                pyhyper_axes_to_use = []
                for x in axes_to_include:
                    try:
                        pyhyper_axes_to_use.append(reverse_lut[x])
                    except KeyError:
                        pyhyper_axes_to_use.append(x)
                dims = pyhyper_axes_to_use

        data = run["primary"]["data"][md["detector"] + "_image"]
        if isinstance(data,tiled.client.array.ArrayClient):
            data = run["primary"]["data"].read()[md["detector"] + "_image"]
        elif isinstance(data,tiled.client.array.DaskArrayClient):
            data = run["primary"]["data"].read()[md["detector"] + "_image"]
        # Handle extra dimensions (non-pixel and non-intended dimensions from repeat exposures) by averaging them along the dim_0 axis
        if len(data.shape) > 3:
            data = data.mean("dim_0", keepdims=True)

        data = data.astype(int)  # convert from uint to handle dark subtraction

        if self.dark_subtract:
            dark = run["dark"]["data"][md["detector"] + "_image"]
            if (
                type(dark) == tiled.client.array.ArrayClient
                or type(dark) == tiled.client.array.DaskArrayClient
            ):
                dark = run["dark"]["data"].read()[md["detector"] + "_image"]
            darkframe = np.copy(data.time)
            for n, time in enumerate(dark.time):
                darkframe[(data.time - time) > 0] = int(n)
            data = data.assign_coords(dark_id=("time", darkframe))

            def subtract_dark(img, pedestal=100, darks=None):
                dark_idx = _scalarize_dark_index(img.dark_id.values)
                return img + pedestal - darks[dark_idx]

            data = data.groupby("time",squeeze=False).map(subtract_dark, darks=dark, pedestal=self.dark_pedestal)

        dims_to_join = []
        dim_names_to_join = []

        for dim in dims:
            try:
                test = len(md[dim])  # this will throw a typeerror if single value
                if type(md[dim]) == dask.array.core.Array:
                    dims_to_join.append(md[dim].compute())
                else:
                    dims_to_join.append(md[dim])
                dim_names_to_join.append(dim)
            except TypeError:
                dims_to_join.append([md[dim]] * run.start["num_points"])
                dim_names_to_join.append(dim)

        for key, val in coords.items():
            dims_to_join.append(val)
            dim_names_to_join.append(key)

        index = pd.MultiIndex.from_arrays(dims_to_join, names=dim_names_to_join)
        # handle the edge case of a partly-finished scan
        if len(index) != len(data["time"]):
            index = index[: len(data["time"])]
        mindex_coords = xr.Coordinates.from_pandas_multiindex(index, 'system')
        retxr = (
            data.sum("dim_0")
            .rename({"dim_1": "pix_y", "dim_2": "pix_x"})
            .rename({"time": "system"})
            .assign_coords(mindex_coords)
        )  # ,md['detector']+'_image':'intensity'})

        # this is needed for holoviews compatibility, hopefully does not break other features.
        retxr = retxr.assign_coords(
            {
                "pix_x": np.arange(0, len(retxr.pix_x)),
                "pix_y": np.arange(0, len(retxr.pix_y)),
            }
        )
        try:
            monitors = (
                monitors.rename({"time": "system"})
                .reset_index("system")
                .assign_coords(mindex_coords)
            )

            if "system_" in monitors.indexes.keys():
                monitors = monitors.drop("system_")

        except Exception as e:
            warnings.warn(
                (
                    "Monitor streams loaded successfully, but could not be correlated to images. "
                    " Check monitor stream for issues, probable metadata change."
                ),
                stacklevel=2,
            )
        retxr.attrs.update(md)

        exposure = retxr.attrs.get("exposure")

        if exposure is not None:
            retxr.attrs["exposure"] = (len(data.dim_0) * exposure)
        else:
            retxr.attrs["exposure"] = None  # or 0, or skip setting it  # patch for multi exposures

        # now do corrections:
        frozen_attrs = retxr.attrs
        if self.corr_mode == "i0":
            retxr = retxr / monitors["RSoXS Au Mesh Current"]
        elif self.corr_mode != "none":
            warnings.warn(
                "corrections other than none or i0 are not supported at the moment",
                stacklevel=2,
            )

        retxr.attrs.update(frozen_attrs)

        # deal with the edge case where the LAST energy of a run is repeated... this may need modification to make it correct (did the energies shift when this happened??)
        try:
            if retxr.system[-1] == retxr.system[-2]:
                retxr = retxr[:-1]
        except IndexError:
            pass

        if return_dataset:
            # retxr = (index,monitors,retxr)
            monitors.attrs.update(retxr.attrs)
            retxr = monitors.merge(retxr)

        if self.use_chunked_loading:
            # dask and multiindexes are like PEO and PPO.  They're kinda the same thing and they don't like each other.
            retxr = retxr.unstack("system")

        return retxr

class PFEnergySeriesIntegrator(PFGeneralIntegrator):

    def integrateSingleImage(self,img):
        # for each image: 
        #    get the energy and locate the matching integrator
        #    use that integrator to reduce
        #    return single reduced frame

        #print(f'    img.energy is a {type(img.energy)}, len = {len(img.energy)} and is {img.energy}') 
        #print(f'    img.system is a {type(img.system)}, len = {len(img.energy)} and is {img.system}')
        #print(f'    img.system.levels: {img.indexes["system"].names}')
        #print(f'    img.indexes: {img.indexes}')
        #print(f'    type of system value: {type(getattr(img,"system").values)}')
        #print(f'    shape of system value: {getattr(img,"system").values.shape}')
        en = None
        if 'energy' not in img.indexes and type(img.energy) != float:
            try: 
                multiindex_name = None
                for idx in img.indexes:
                    if type(img.indexes[idx]) == pd.core.indexes.multi.MultiIndex:
                        multiindex_name = idx
                        break
                if 'energy' in img.indexes[multiindex_name].names:
                    for i,n in enumerate(img.indexes[multiindex_name].names):
                        if n == 'energy':
                            idx_of_energy = i
                    try:
                        en = float(getattr(img,multiindex_name).values[idx_of_energy][0]) # this does not work for 2022-2 data; does it work for other cycles?
                    except IndexError:
                        en = float(getattr(img,multiindex_name).values[0][idx_of_energy])
            except KeyError:
                pass
        if en is not None:
            pass
        elif type(img.energy) == float:
            en = img.energy
        else:
            try:
                en = img.energy.values[0]
                if len(img.energy.values)>1:
                    warnings.warn(f'Using the first energy value of {img.energy.values}, check that this is correct.',stacklevel=2)
            except IndexError:
                en = float(img.energy)
            except AttributeError:
                try:
                    en = img.energy[0]
                    warnings.warn(f'Using the first energy value of {img.energy}, if this contains more than one energy, your data are likely wrong.',stacklevel=2)
                except IndexError:
                    en = float(img.energy)

        try:
            self.integrator = self.integrator_stack[en]
        except KeyError:
            self.integrator = self.createIntegrator(en)
        res = super().integrateSingleImage(img)
        try:
            if len(self.dest_q)>0:
                return res.interp(q=self.dest_q)
            else:
                return res
        except (TypeError,AttributeError):
            return res
    def setupIntegrators(self,energies):
        '''
        Sets up the integrator stack as a function of energy.

        The final statement ensures that the integrator for the median of the set is created.  This integrator is used to set
        the output q-binning.

        Details: (copied from a message)

        The fact that energy is changing during reduction means that if not forced to something, the output q bins of the integrator will move as well (since the pixel to q mappings are moving with energy). Because sparse data in q is a nightmare, we pick a given set of q bins corresponding to the median of the energies in the scan. That is a compromise between a few approaches. This line manually creates that integrator with default q binning settings so we can take those bins and tell all the other integrators to use that output q grid.

It would cosmically be better (for things like resolution calculation) to have the q bins actually move, but sparse arrays are computationally hard. Eventually (2-3 years of high performance Python evolution) I think that will be the right way to do it, this is an intermediate.
        '''
        for en in energies:
            self.createIntegrator(en)
        self.createIntegrator(np.median(energies))
    def setupDestQ(self,energies):
        self.dest_q = self.integrator_stack[np.median(energies)].integrate2d(np.zeros_like(self.mask).astype(int), self.npts, 
                                                   unit='arcsinh(q.µm)' if self.use_log_ish_binning else 'q_A^-1',
                                                   method=self.integration_method).radial

    def integrateImageStack_dask(self,img_stack,chunksize=5):
        self.setupIntegrators(img_stack.energy.data)
        self.setupDestQ(img_stack.energy.data)
        indexes = list(img_stack.dims)
        indexes.remove('pix_x')
        indexes.remove('pix_y')

        # idx_name_to_use = 'energy'#indexes[0]
        # idx_val_to_use = img_stack.indexes[idx_name_to_use]


        if 'energy' in indexes:
            dim_to_chunk = 'energy'
        else:
            dim_to_chunk = indexes[0]
            #this probably should check which is the longest?  Shortest?  and chunk that.
        print(f'chunking on {dim_to_chunk}')

        coord_dict = {}
        shape = tuple([])
        order_list = []
        for idx in indexes:
            order_list.append(idx)
            coord_dict[idx] = img_stack.indexes[idx]
            shape = shape + tuple([len(img_stack.indexes[idx])])
        shape = (360,self.npts) + shape 


        fake_image_to_process = img_stack.isel(**{dim_to_chunk:0},drop=False)
        #fake_image_to_process.attrs['energy'] = img_stack.energy.isel(**{idx_name_to_use:0})
        demo_integration = self.integrateSingleImage(fake_image_to_process)
        coord_dict.update({'chi':demo_integration.chi,'q':self.dest_q})

        desired_order_list = ['chi','q']+order_list
        coord_dict_sorted = {k: coord_dict[k] for k in desired_order_list}

        template = xr.DataArray(np.empty(shape),coords=coord_dict_sorted)


        template = template.chunk({dim_to_chunk:chunksize})
        if 'image_num' in demo_integration.dims:
            template = template.transpose(*[item if item != 'image_num' else dim_to_chunk for item in demo_integration.dims])

        integ_fly = img_stack.chunk({dim_to_chunk:chunksize}).map_blocks(self.integrateImageStack_legacy,template=template)#integ_traditional.chunk({'energy':5}))
        return integ_fly 

    def integrateImageStack_legacy(self,img_stack):
        # get just the energies of the image stack
       # if type(img_stack.energy)== np.ndarray:

        # get just the energies of the image stack
        #energies = img_stack.energy.to_dataframe()

        #energies = energies['energy'].drop_duplicates()
        energies = np.unique(img_stack.energy.data)
        #create an integrator for each energy
        self.setupIntegrators(energies)
        # find the output q for the midpoint and set the final q binning
        if not hasattr(self,'dest_q'):
            try:
                self.setupDestQ(energies)
            except TypeError as e:
                if 'diffSolidAngle() missing 2 required positional arguments: ' in str(e):
                    raise TypeError('Geometry is incorrect, cannot integrate.\n \n - Do your mask dimensions match your image dimensions? \n - Do you have pixel sizes set that are not zero?\n - Is SDD, beamcenter/poni, and tilt set correctly?') from e
                else:
                    raise e
        if self.use_log_ish_binning:
            self.dest_q = np.sinh(self.dest_q)/10000
        # single image reduce each entry in the stack
        # + 
        # restack the reduced data
        data = img_stack
        indexes = list(data.dims)
        indexes.remove('pix_x')
        indexes.remove('pix_y')

        # the following section attempts to shape the array that we have so that it meets the requirements for the xarray GroupBy/map
        # paradigm; specifically, it needs one index that's not pixel x/y.  We either identify if that is the case, or we make it the
        # case.  however, there are probably edge cases not handled here

        if len(indexes) == 1:
            if img_stack.__getattr__(indexes[0]).to_pandas().drop_duplicates().shape[0] != img_stack.__getattr__(indexes[0]).shape[0]:
                warnings.warn(f'Axis {indexes[0]} contains duplicate conditions.  This is not supported and may not work.  Try adding additional coords to separate image conditions',stacklevel=2)
            data_int = data.groupby(indexes[0],squeeze=False).progress_apply(self.integrateSingleImage)
        elif len(indexes) == 0:
            data_int = self.integrateSingleImage(data).isel(image_num=0)
        else:
            #some kinda logic to check for existing multiindexes and stack into them appropriately maybe
            data = data.stack({'pyhyper_internal_multiindex':indexes})
            if data.pyhyper_internal_multiindex.to_pandas().drop_duplicates().shape[0] != data.pyhyper_internal_multiindex.shape[0]:
                warnings.warn('Your index set contains duplicate conditions.  This is not supported and may not work.  Try adding additional coords to separate image conditions',stacklevel=2)

            data_int = data.groupby('pyhyper_internal_multiindex',squeeze=False).progress_apply(self.integrateSingleImage).unstack('pyhyper_internal_multiindex')
        return data_int
        #return img_stack.groupby('system',squeeze=False).progress_apply(self.integrateSingleImage)

    def integrateImageStack(self,img_stack,method=None,chunksize=None):
        '''

        '''

        if (self.use_chunked_processing and method is None) or method=='dask':
            func_args = {}
            if chunksize is not None:
                func_args['chunksize'] = chunksize
            return self.integrateImageStack_dask(img_stack,**func_args)
        elif (method is None) or method == 'legacy':
            return self.integrateImageStack_legacy(img_stack)
        else:
            raise NotImplementedError(f'unsupported integration method {method}')



    def createIntegrator(self,en,recreate=False):
        if en not in self.integrator_stack.keys() or recreate:
            self.integrator_stack[en] = azimuthalIntegrator.AzimuthalIntegrator(
            self.dist, self.poni1, self.poni2, self.rot1, self.rot2, self.rot3 ,pixel1=self.pixel1,pixel2=self.pixel2, wavelength = 1.239842e-6/en)
        return self.integrator_stack[en]
    def __init__(self,**kwargs):
        self.integrator_stack = {}

        super().__init__(**kwargs)
    def recreateIntegrator(self):
        pass

    def __str__(self):
        return f"PyFAI energy-series integrator  SDD = {self.dist} m, poni1 = {self.poni1} m, poni2 = {self.poni2} m, rot1 = {self.rot1} rad, rot2 = {self.rot2} rad"

def _resolve_metadata(self, img, metadata_kwargs):
    fallback = dict(self._default_metadata)
    fallback.update(metadata_kwargs)

    shape_zyx = self._shape_from_attrs(img.attrs)
    if shape_zyx is None:
        shape_zyx = self._shape_from_value(fallback.get("shape_zyx"))

    z_dim = self._z_dim_from_attrs(img.attrs)
    if z_dim is None and shape_zyx is not None:
        z_dim = int(shape_zyx[0])
    if z_dim is None and fallback.get("z_dim") is not None:
        z_dim = int(fallback["z_dim"])
    if z_dim is None and fallback.get("shape_zyx") is not None:
        z_dim = int(self._shape_from_value(fallback["shape_zyx"])[0])

    projection_mode = self._projection_mode_from_attrs(img.attrs)
    if projection_mode is None and fallback.get("projection_mode") is not None:
        projection_mode = str(fallback["projection_mode"]).strip().lower()

    phys_size_nm = self._phys_size_from_attrs(img.attrs)
    if phys_size_nm is None and fallback.get("phys_size_nm") is not None:
        phys_size_nm = float(fallback["phys_size_nm"])

    validate_q_coords_against_phys_size = fallback.get("validate_q_coords_against_phys_size", "raise")
    if phys_size_nm is not None and validate_q_coords_against_phys_size:
        self._validate_q_axes_against_phys_size(
            img=img,
            phys_size_nm=phys_size_nm,
            mode=validate_q_coords_against_phys_size,
        )

    energy_ev = self._energy_from_attrs_or_coords(img)
    if energy_ev is None and fallback.get("energy_ev") is not None:
        energy_ev = float(fallback["energy_ev"])

    nrss_semantic_mode = self._semantic_mode(projection_mode=projection_mode, z_dim=z_dim)
    radial_semantics = "q_perp"
    if nrss_semantic_mode == "3d_detector_aware":
        radial_semantics = "q_abs_detector_corrected"
        if energy_ev is None:
            raise ValueError(
                "NRSSIntegrator needs a scalar energy for detector-aware 3D reductions. "
                "Populate img.attrs['energy_ev'], provide a scalar energy coordinate, or pass energy_ev=..."
            )

    return {
        "phys_size_nm": phys_size_nm,
        "shape_zyx": shape_zyx,
        "z_dim": z_dim,
        "energy_ev": energy_ev,
        "nrss_semantic_mode": nrss_semantic_mode,
        "radial_semantics": radial_semantics,
    }

def integrateImageStack_batched(self, data, **metadata_kwargs):
    stacked, stacked_name, index_dims, spatial_dims = self._prepare_batched_input(data)
    values = np.asarray(stacked.values)
    if values.ndim != 3:
        raise ValueError(f"NRSSIntegrator expected stacked data with 3 dims, got shape {values.shape!r}.")

    metadata = [self._resolve_metadata(stacked.isel({stacked_name: i}, drop=False), metadata_kwargs) for i in range(values.shape[0])]
    reduced_values, q_axes, q_perp_axis, chi, common_attrs, common_mode, q_semantics_vary = (
        self._integrate_batched_array(stacked, values, metadata, spatial_dims)
    )

    result = xr.DataArray(
        reduced_values,
        dims=[stacked_name, "chi", "q"],
        coords={
            stacked_name: stacked.coords[stacked_name],
            "chi": chi,
        },
        attrs=common_attrs,
    )

    result = self._assign_output_q_coords(result, stacked_name, q_axes, q_perp_axis, common_mode, q_semantics_vary)

    if len(index_dims) == 0:
        return result.isel({stacked_name: 0}, drop=True)
    if len(index_dims) > 1:
        result = result.unstack(stacked_name)
        result = result.transpose(*index_dims, "chi", "q")
    return result

def update_optical_constants(self):
    # Pre-allocate list to avoid repeated allocations
    all_constants = [None] * self._numMaterial
    for energy in self.Energies:
        # Update list in-place
        for ID in range(1, self.numMaterial+1):
            all_constants[ID-1] = self.materials[ID].opt_constants[energy]
        self.OpticalConstants.addData(OpticalConstants=all_constants, Energy=energy)

def check_materials(self, quiet=True):
    # Vectorized sum of volume fractions
    Vfrac_sum = sum(mat.Vfrac for mat in self.materials.values())
    assert np.allclose(Vfrac_sum, 1), 'Total material volume fractions do not sum to 1'
    del Vfrac_sum  # Free memory immediately

    # Check each material's properties
    for i, mat in self.materials.items():
        # Validate value ranges and types in one pass
        for name, arr in {
            'S': mat.S,
            'Vfrac': mat.Vfrac,
            'theta': mat.theta,
            'psi': mat.psi
        }.items():
            # Check for NaNs and float type in one operation
            if not np.issubdtype(arr.dtype, np.floating):
                raise AssertionError(f'Material {i} {name} is not of type float')

            if np.any(np.isnan(arr)):
                raise AssertionError(f'NaNs are present in Material {i} {name}')

            # Check bounds for S and Vfrac
            if name in ('S', 'Vfrac'):
                if not np.all((arr >= 0) & (arr <= 1)):
                    raise AssertionError(f'Material {i} {name} value(s) does not lie between 0 and 1')

    if not quiet:
        print('All material checks have passed')
